import{_ as t,o,c as r,a2 as n}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"06. Instructor Teaching Notes, Common Pitfalls, & Student Exercises","description":"","frontmatter":{},"headers":[],"relativePath":"06-instructor-notes.md","filePath":"06-instructor-notes.md"}'),a={name:"06-instructor-notes.md"};function i(s,e,d,c,l,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_06-instructor-teaching-notes-common-pitfalls-student-exercises" tabindex="-1">06. Instructor Teaching Notes, Common Pitfalls, &amp; Student Exercises <a class="header-anchor" href="#_06-instructor-teaching-notes-common-pitfalls-student-exercises" aria-label="Permalink to &quot;06. Instructor Teaching Notes, Common Pitfalls, &amp; Student Exercises&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">PEDAGOGICAL INSIGHT: CHIP VARIANT COMPATIBILITY</p><p><strong>The 157A vs 157D Hardware Nuance:</strong> In this lab, the defconfig <code>st_stm32mp157a_dk1_defconfig</code> was used on an <strong>STM32MP157D</strong> board.</p><ul><li><strong>STM32MP157A:</strong> Rated clock frequency up to 650 MHz (no hardware crypto engine).</li><li><strong>STM32MP157D:</strong> Rated clock frequency up to 800 MHz (includes hardware crypto engine).</li></ul><p>Because clock setups in the 157A defconfig bootloader run the core at 650 MHz, running the 157A binary image on a 157D chip safely underclocks the hardware. While safe for testing, instructors should emphasize that production builds must match exact chip sub-variants to utilize full performance and peripheral hardware features.</p></div><hr><h2 id="troubleshooting-common-student-errors" tabindex="-1">Troubleshooting &amp; Common Student Errors <a class="header-anchor" href="#troubleshooting-common-student-errors" aria-label="Permalink to &quot;Troubleshooting &amp; Common Student Errors&quot;">​</a></h2><ol><li><strong>Permission Denied on <code>/dev/ttyACM0</code>:</strong> Students forget to add their host user account to the <code>dialout</code> group or fail to re-login to update group privileges.</li><li><strong>No Output on Serial Terminal:</strong> Verify physical baud rate (must be set to 115200). Ensure Micro-USB cable supports data communication, not power only.</li><li><strong>Target Fails to Boot from SD Card:</strong> Verify DIP switches <code>BOOT0</code> and <code>BOOT2</code> are flipped to ON. Verify that <code>dd</code> was flashed to the raw disk node (<code>/dev/mmcblk2</code>) and that <code>sync</code> was executed before card extraction.</li></ol><hr><h2 id="student-review-questions" tabindex="-1">Student Review Questions <a class="header-anchor" href="#student-review-questions" aria-label="Permalink to &quot;Student Review Questions&quot;">​</a></h2><ol><li>Contrast bare-metal programming with Embedded Linux in terms of real-time determinism, memory requirements, and code portability.</li><li>Explain the function of a Memory Management Unit (MMU) and state why it is mandatory for running standard Embedded Linux.</li><li>Describe the architecture of a Heterogeneous Multi-Core SoC (e.g., STM32MP1) and explain how task allocation is divided between MPU and MCU cores.</li><li>Compare Buildroot and the Yocto Project. Under what conditions would an engineering team choose Buildroot over Yocto?</li><li>Trace the boot sequence of an embedded Linux target from power-on reset to the root login prompt.</li></ol><hr><div class="info custom-block"><p class="custom-block-title">SUMMARY OF KEY CONCEPTS</p><p>Embedded Linux provides an unparalleled ecosystem for building powerful, networked, and portable embedded products. By leveraging automated build frameworks like Buildroot, developers eliminate bloat, minimize hardware footprint, achieve fast boot times, and maintain complete control over every binary included in production devices.</p></div>',10)])])}const p=t(a,[["render",i]]);export{h as __pageData,p as default};
